"""Native declaration combination refuses conflicting labels and canonical duplicates."""
from pathlib import Path
import sys,json,subprocess,re
from interlock.case_template import case_template,REFERENCE_EXPECTATIONS
root=Path(sys.argv[1]);a=root/'left.json';b=root/'right.json';left=case_template(['retry-conflict','retry-fixed']);right=case_template(['retry-fixed','cancellation-fixed']);a.write_text(json.dumps(left));b.write_text(json.dumps(right));before=[a.read_bytes(),b.read_bytes()];base=[sys.executable,'-m','interlock','combine-case-manifests',str(a),str(b)];expected={'format':left['format'],'cases':[*left['cases'],right['cases'][1]]};r=subprocess.run(base,capture_output=True,text=True);assert r.returncode==0,r.stderr;assert json.loads(r.stdout)==expected;h=subprocess.run(base+['--html'],capture_output=True,text=True);assert h.returncode==0,h.stderr;assert json.loads(re.search(r'<script id="report-data" type="application/json">(.*?)</script>',h.stdout,re.S).group(1))==expected;(root/'combined.html').write_text(h.stdout);(root/'expected.json').write_text(json.dumps(expected));assert[a.read_bytes(),b.read_bytes()]==before
code="from unittest.mock import patch;from interlock.cli import main\nwith patch('interlock.model_cases.check_many',side_effect=RuntimeError('search forbidden')),patch('interlock.fixture.check_fixture',side_effect=RuntimeError('handlers forbidden')):raise SystemExit(main("+repr(base[3:])+"))";r=subprocess.run([sys.executable,'-c',code],capture_output=True);assert r.returncode==0
bad=json.loads(before[1]);bad['cases'][0]['expected_status']='branch_failure';b.write_text(json.dumps(bad));r=subprocess.run(base,capture_output=True);assert r.returncode==2 and not r.stdout
bad=json.loads(before[1]);bad['cases'][0]['id']='same-scenario-new-id';b.write_text(json.dumps(bad));r=subprocess.run(base,capture_output=True);assert r.returncode==2 and not r.stdout
